<template><section class="sample-workbench"><div class="page-head"><h2>打样室</h2><button class="btn btn-ghost" @click="load">刷新列表</button></div><nav><button v-for="t in tabs" :key="t[0]" :class="{on:tab===t[0]}" @click="tab=t[0]">{{t[1]}} {{rows.filter(r=>match(r,t[0])).length}}</button></nav><input class="input" v-model="q" placeholder="订单号 / 款号 / 客户"/><p v-if="error" role="alert">{{error}}</p><div class="sample-scroll"><table><thead><tr><th>样衣 / 款号</th><th>订单号</th><th>客户</th><th>版本</th><th>当前阶段</th><th>审核状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td><img v-if="r.image_url" :src="r.image_url" @click="openImage(r.image_url,r.product_name)"/>{{r.customer_style_no||r.product_name}}</td><td>{{r.order_no||'—'}}</td><td>{{r.customer_name||'—'}}</td><td>{{r.version}}</td><td>{{r.current_stage}}</td><td>{{r.change_hold?'待审核 / 复核':r.status==='done'?'已完成':'进行中'}}</td><td><router-link :to="{path:'/pattern-board',query:{techpack:r.tech_pack_id}}">办理工艺与打版</router-link><button class="link-btn" @click="cost(r)">面辅料 / 扫码工价核对</button></td></tr><tr v-if="!filtered.length"><td colspan="7">此范围暂无样衣</td></tr></tbody></table></div><div v-if="evidence" class="modal-mask"><section class="modal"><div class="modal-head"><h3>样衣成本证据 · {{evidence.version}}</h3><button class="x" @click="evidence=null">×</button></div><div class="modal-body"><p>面辅料单件金额：{{evidence.material_unit_cost==null?'—':evidence.material_unit_cost+' 元'}}（{{evidence.material_rows}}行）</p><p>已归款扫码金额：{{evidence.scan_known_amount==null?'—':evidence.scan_known_amount+' 元'}}（{{evidence.scan_rows}}条）</p><p>缺单价 {{evidence.missing_price_rows}} 条 · 待归款 {{evidence.unallocated_rows}} 条</p><p>{{evidence.limitation}}</p></div><div class="modal-foot"><button @click="evidence=null">关闭</button></div></section></div></section></template>
<script setup>import {ref,computed,onMounted} from 'vue';import {api} from '../api';import {openImage} from '../store/viewer';const rows=ref([]),tab=ref('active'),q=ref(''),error=ref(''),evidence=ref(null);const tabs=[['active','在产样衣'],['confirm','待确认样衣'],['craft','待打工价款'],['cost','待核成本款'],['cut','待裁样衣单']];function match(r,k){return k==='active'?r.status!=='done':k==='confirm'?r.change_hold||['biz','audit'].includes(r.current_stage):k==='craft'?r.current_stage==='craft':k==='cut'?r.current_stage==='pattern':r.current_stage==='audit';}const filtered=computed(()=>rows.value.filter(r=>match(r,tab.value)&&[r.order_no,r.pre_order_no,r.customer_style_no,r.product_name,r.customer_name].some(v=>String(v||'').toLowerCase().includes(q.value.toLowerCase()))));async function load(){error.value='';try{rows.value=(await api.patternBoard()).flows||[];}catch(e){error.value=e.message;rows.value=[];}}async function cost(r){try{evidence.value=await api.sampleCostEvidence(r.tech_pack_id);}catch(e){error.value=e.message;}}onMounted(load);</script><style scoped>nav{display:flex;gap:8px;flex-wrap:wrap;background:var(--surface-2);padding:16px;border:1px solid var(--line)}nav button{padding:10px 18px;border:1px solid var(--line);background:var(--surface);color:var(--ink);cursor:pointer}nav .on{background:var(--brand);color:white}.sample-workbench>.input{margin:16px 0;width:300px}.sample-scroll{overflow:auto}table{width:100%;min-width:1000px;border-collapse:collapse;background:var(--surface);font-size:12px}th,td{border:1px solid var(--line);padding:14px;text-align:left}th{background:var(--surface-2)}td img{height:80px;width:65px;object-fit:contain;vertical-align:middle;margin-right:14px;cursor:zoom-in}td button{display:block;margin-top:10px}</style>
